import React, { useState } from 'react';
import ReviewItem from './ReviewItem';
import ReviewForm from './ReviewForm';
import './Reviews.css';

const ReviewsSection = ({ tourId }) => {
  // 🔹 МОКИ (потом придут с API)
  const [reviews, setReviews] = useState([
    {
      id: 1,
      rating: 5,
      commenting: 'Очень понравилась экскурсия!',
      created_at: '2025-06-01',
      author: 'Иван'
    },
    {
      id: 2,
      rating: 4,
      commenting: 'Хорошая организация, но было жарко',
      created_at: '2025-06-03',
      author: 'Мария'
    }
  ]);

  // 🔹 временные флаги
  const isAuth = true;
  const hasOrder = true;
  const hasReview = false;

  const canAddReview = isAuth && hasOrder && !hasReview;

  const handleAddReview = (newReview) => {
    setReviews(prev => [newReview, ...prev]);
  };

  return (
    <section className="reviews">
      <h2 className="reviews-title">Отзывы</h2>

      {canAddReview && (
        <ReviewForm onSubmit={handleAddReview} />
      )}

      {reviews.length === 0 ? (
        <p className="reviews-empty">Отзывов пока нет</p>
      ) : (
        <div className="reviews-list">
          {reviews.map(review => (
            <ReviewItem key={review.id} review={review} />
          ))}
        </div>
      )}
    </section>
  );
};

export default ReviewsSection;
